    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0
    max_opp_budget = max(opp_budgets) if opp_budgets else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        bid = max(88.0, highest_prev + 4.0)
        if tight_supply:
            bid += 10.0
        return max(0.0, min(budget, bid))

    if hp <= 4 or no_water_days >= 1:
        bid = max(62.0, avg_prev + 3.0)
        if tight_supply:
            bid += 8.0
        elif ample_supply:
            bid -= 6.0
        if urgent_opponents >= 1:
            bid += 5.0
        return max(0.0, min(budget, bid))

    bid = 36.0
    if tight_supply:
        bid = max(48.0, avg_prev * 0.62)
    elif ample_supply:
        bid = max(24.0, avg_prev * 0.38)
    else:
        bid = max(34.0, avg_prev * 0.5)

    if highest_prev >= 100.0:
        bid = min(bid, 52.0)
    if urgent_opponents >= 2:
        bid += 6.0
    if budget < DAILY_SALARY * 2:
        bid = min(bid, 40.0)
    if max_opp_budget < budget * 0.5:
        bid += 4.0

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))

    # Alive opponents only
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no one is alive, spend only enough to meet requirement safely
    if not alive_opps:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Use yesterday highest bid as pressure signal
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids)) if yesterday_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Supply pressure: higher supply reduces urgency; lower supply increases urgency
    # Map supply in [MIN_SUPPLY, MAX_SUPPLY] to a factor in [1.15, 0.85]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 1.0
    else:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        supply_factor = 1.15 - 0.30 * t

    # Core target bid band derived from yesterday traces:
    # Alex/Cindy were ~100+, Eric ~73. Use a weighted target.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base_target = max(avg_prev_bid, highest_prev_bid * 0.9)
    else:
        base_target = max(avg_prev_bid, DAILY_SALARY * 0.55)

    # If supply is low, push slightly higher; if high, pull back.
    target = base_target * supply_factor

    # HP-based risk control: if low HP, avoid overbidding; if healthy, be more aggressive.
    if my_hp <= 2.0:
        target *= 0.75
    elif my_hp <= 4.0:
        target *= 0.9
    else:
        target *= 1.05

    # Don't exceed budget; also keep within a reasonable fraction of daily salary to avoid depletion.
    # (We still allow higher than salary if budget is large and pressure is high.)
    cap = my_budget
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        cap = min(cap, DAILY_SALARY * 1.35)
    else:
        cap = min(cap, DAILY_SALARY * 1.10)

    bid = max(0.0, min(cap, target))

    # Ensure we always bid at least a small amount if budget allows
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.25)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If no opponents, bid low to save money, but ensure water
    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = 0
    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)

    # Calculate total water needed for all alive players + self
    total_water_needed = WATER_REQ # My requirement
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    # Determine bidding strategy based on HP and supply/competition

    # Aggressive bidding if HP is very low (e.g., 1 day left)
    if my_status['hp'] <= 1:
        # Bid high to ensure survival, capped by daily salary
        return min(my_status['budget'], DAILY_SALARY, DAILY_SALARY * 0.95)

    # Moderate aggressive if HP is low (e.g., 2-3 days left)
    if my_status['hp'] <= 3:
        # If supply is very tight or competition was high yesterday
        if current_supply < total_water_needed or max_yesterday_bid > DAILY_SALARY * 0.7:
            return min(my_status['budget'], DAILY_SALARY, DAILY_SALARY * 0.8)
        else:
            # Still bid relatively high, but not max, capped by daily salary
            return min(my_status['budget'], DAILY_SALARY, DAILY_SALARY * 0.7)

    # If HP is good (more than 3 days)
    # Check for supply abundance
    if current_supply >= total_water_needed: # Supply is enough for everyone to get their required water
        # If yesterday's bids were high, we can try to undercut slightly or match, capped by daily salary
        if max_yesterday_bid > DAILY_SALARY * 0.5:
            return min(my_status['budget'], DAILY_SALARY, max(DAILY_SALARY * 0.4, max_yesterday_bid * 0.9))
        else:
            # Low competition, ample supply, bid low to save, capped by daily salary
            return min(my_status['budget'], DAILY_SALARY, DAILY_SALARY * 0.3)
    else: # Supply is tight, not enough for everyone to get their required water
        # If yesterday's bids were high, we need to be competitive, capped by daily salary
        if max_yesterday_bid > DAILY_SALARY * 0.6:
            # Bid slightly above the max yesterday bid to win, but not exceeding salary
            return min(my_status['budget'], DAILY_SALARY, max(DAILY_SALARY * 0.65, max_yesterday_bid + 5))
        else:
            # Competition not too high yesterday, but supply is tight, bid moderately, capped by daily salary
            return min(my_status['budget'], DAILY_SALARY, DAILY_SALARY * 0.6)

    # Fallback bid (should not be reached with current logic), capped by daily salary
    return min(my_status['budget'], DAILY_SALARY, DAILY_SALARY * 0.5)

